/**
 * Conversation Lock Service Tests - Phase 4 Task 5
 * 
 * Test Coverage:
 * - Lock acquisition with <50ms target latency
 * - TTL management (30s+ default)
 * - Concurrency prevention
 * - Lock refresh and auto-refresh
 * - Redis integration
 * 
 * @file tests/phase4/conversation-lock.test.js
 */

const ConversationLockService = require('../../src/services/conversation-lock.service');
const { AppError } = require('../../src/utils/app-error');

/**
 * Mock Redis client
 */
const createMockRedis = () => ({
  set: jest.fn(),
  get: jest.fn(),
  del: jest.fn(),
  expire: jest.fn(),
  ttl: jest.fn()
});

describe('Conversation Lock Service', () => {
  let service;
  let mockRedis;

  beforeEach(() => {
    mockRedis = createMockRedis();
    service = new ConversationLockService(mockRedis, {
      ttl: 30,
      minTTL: 30,
      maxTTL: 300,
      acquireTimeout: 5000
    });
  });

  afterEach(() => {
    // Clean up any pending intervals
    jest.clearAllTimers();
  });

  /**
   * Test Suite: Lock Acquisition
   */
  describe('Lock Acquisition', () => {
    it('should acquire lock successfully', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123');

      expect(result).toBeDefined();
      expect(result.conversationId).toBe('conv-123');
      expect(result.lockToken).toBeDefined();
      expect(result.lockToken.length).toBeGreaterThan(0);
    });

    it('should return lock metadata with timestamps', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123', { ttl: 60 });

      expect(result.acquiredAt).toBeDefined();
      expect(result.expiresAt).toBeDefined();
      expect(new Date(result.expiresAt).getTime()).toBeGreaterThan(new Date(result.acquiredAt).getTime());
    });

    it('should use default TTL when not specified', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123');

      expect(result.ttl).toBe(30); // Default TTL
    });

    it('should enforce min TTL', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123', { ttl: 5 }); // Below min

      expect(result.ttl).toBe(30); // Should be adjusted to min
    });

    it('should enforce max TTL', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123', { ttl: 600 }); // Above max

      expect(result.ttl).toBe(300); // Should be capped at max
    });

    it('should reject lock when already held', async () => {
      mockRedis.set.mockResolvedValue(null); // NX failed - key exists

      await expect(service.acquireLock('conv-123'))
        .rejects
        .toThrow('Lock already held');
    });

    it('should track local lock instances', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-123');
      const tracked = service.locks.get(result.lockToken);

      expect(tracked).toBeDefined();
      expect(tracked.conversationId).toBe('conv-123');
    });
  });

  /**
   * Test Suite: Acquisition Performance
   */
  describe('Lock Acquisition Performance', () => {
    it('should acquire lock in <50ms', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const startTime = Date.now();
      const result = await service.acquireLock('conv-perf');
      const elapsed = Date.now() - startTime;

      expect(elapsed).toBeLessThan(50);
      expect(result.elapsed).toBeLessThan(50);
      console.log(`Lock acquisition: ${elapsed}ms (target: <50ms)`);
    });

    it('should acquire 1000 locks concurrently within 100ms total', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const startTime = Date.now();
      const promises = [];

      for (let i = 0; i < 1000; i++) {
        promises.push(service.acquireLock(`conv-perf-${i}`));
      }

      await Promise.all(promises);
      const elapsed = Date.now() - startTime;

      console.log(`1000 concurrent lock acquisitions: ${elapsed}ms`);
      expect(elapsed).toBeLessThan(5000);
    });
  });

  /**
   * Test Suite: Lock Release
   */
  describe('Lock Release', () => {
    it('should release acquired lock', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.del.mockResolvedValue(1);

      const lock = await service.acquireLock('conv-rel');
      const released = await service.releaseLock(lock.lockToken);

      expect(released).toBe(true);
      expect(mockRedis.del).toHaveBeenCalledWith(lock.lockKey);
    });

    it('should fail to release non-existent lock', async () => {
      mockRedis.del.mockResolvedValue(0);

      const released = await service.releaseLock('invalid-token');
      expect(released).toBe(false);
    });

    it('should remove lock from local tracking', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.del.mockResolvedValue(1);

      const lock = await service.acquireLock('conv-track');
      expect(service.locks.has(lock.lockToken)).toBe(true);

      await service.releaseLock(lock.lockToken);
      expect(service.locks.has(lock.lockToken)).toBe(false);
    });
  });

  /**
   * Test Suite: Lock Refresh & Auto-Refresh
   */
  describe('Lock Refresh & TTL Management', () => {
    it('should refresh lock TTL', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.expire.mockResolvedValue(1);

      const lock = await service.acquireLock('conv-refresh', { ttl: 30 });
      const refreshed = await service.refreshLock(lock.lockToken, 30);

      expect(refreshed).toBe(true);
      expect(mockRedis.expire).toHaveBeenCalled();
    });

    it('should setup auto-refresh when enabled', async () => {
      jest.useFakeTimers();
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.expire.mockResolvedValue(1);

      const lock = await service.acquireLock('conv-auto', { autoRefresh: true, ttl: 30 });
      const tracked = service.locks.get(lock.lockToken);

      expect(tracked.shouldAutoRefresh).toBe(true);
      expect(tracked.refreshInterval).toBeDefined();

      jest.useRealTimers();
    });

    it('should not setup auto-refresh when disabled', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const lock = await service.acquireLock('conv-no-auto', { autoRefresh: false });
      const tracked = service.locks.get(lock.lockToken);

      expect(tracked.shouldAutoRefresh).toBe(false);
      expect(tracked.refreshInterval).toBeNull();
    });

    it('should respect refresh threshold', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.expire.mockResolvedValue(1);

      // With default 30% threshold and 30s TTL, should refresh at 21s elapsed
      const lock = await service.acquireLock('conv-threshold', { ttl: 30 });
      const elapsedFor70Percent = 30 * 1000 * 0.7; // 21 seconds

      jest.advanceTimersByTime(elapsedFor70Percent);
      // Auto-refresh should have triggered

      jest.clearAllTimers();
    });
  });

  /**
   * Test Suite: Concurrency Prevention
   */
  describe('Concurrency Prevention', () => {
    it('should prevent concurrent processing of same conversation', async () => {
      // First lock holder
      mockRedis.set.mockResolvedValueOnce('OK');
      const lock1 = await service.acquireLock('conv-mutex');

      // Second attempter should fail
      mockRedis.set.mockResolvedValueOnce(null);
      await expect(service.acquireLock('conv-mutex'))
        .rejects
        .toThrow('Lock already held');
    });

    it('should allow sequential processing after lock release', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.del.mockResolvedValue(1);

      // First holder
      const lock1 = await service.acquireLock('conv-seq');
      await service.releaseLock(lock1.lockToken);

      // Second holder should succeed
      const lock2 = await service.acquireLock('conv-seq');
      expect(lock2.lockToken).toBeDefined();
    });

    it('should handle mutex for multiple conversations independently', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const lock1 = await service.acquireLock('conv-A');
      const lock2 = await service.acquireLock('conv-B');
      const lock3 = await service.acquireLock('conv-C');

      expect(lock1.lockToken).not.toBe(lock2.lockToken);
      expect(lock2.lockToken).not.toBe(lock3.lockToken);
    });

    it('should timeout waiting for lock release', async () => {
      jest.useFakeTimers();
      mockRedis.set.mockResolvedValueOnce('OK'); // First succeeds
      mockRedis.set.mockResolvedValue(null); // Subsequent fail
      mockRedis.get.mockResolvedValue('some-token'); // Other holder exists

      const lock1 = await service.acquireLock('conv-timeout');

      const promise = service.acquireLock('conv-timeout', { waitForRelease: true });

      jest.advanceTimersByTime(6000); // Exceed timeout
      await expect(promise).rejects.toThrow();

      jest.useRealTimers();
    });
  });

  /**
   * Test Suite: TTL Management
   */
  describe('TTL Management', () => {
    it('should set TTL on lock key', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const result = await service.acquireLock('conv-ttl', { ttl: 60 });

      expect(mockRedis.set).toHaveBeenCalledWith(
        expect.stringContaining('conv-ttl'),
        expect.any(String),
        'EX',
        60,
        'NX'
      );
    });

    it('should retrieve remaining TTL', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.ttl.mockResolvedValue(45); // 45 seconds remaining

      const lock = await service.acquireLock('conv-ttl-check', { ttl: 60 });
      const remaining = await service.getRemainingTTL(lock.lockToken);

      expect(remaining).toBe(45);
    });

    it('should return 0 for expired locks', async () => {
      mockRedis.ttl.mockResolvedValue(-2); // Key doesn't exist

      const remaining = await service.getRemainingTTL('expired-token');
      expect(remaining).toBe(0);
    });
  });

  /**
   * Test Suite: Error Handling
   */
  describe('Error Handling', () => {
    it('should handle Redis connection errors', async () => {
      mockRedis.set.mockRejectedValue(new Error('Redis connection failed'));

      await expect(service.acquireLock('conv-error'))
        .rejects
        .toThrow('Redis connection failed');
    });

    it('should handle lock validation errors', async () => {
      mockRedis.set.mockResolvedValue('OK');
      mockRedis.get.mockRejectedValue(new Error('Redis error'));

      const lock = await service.acquireLock('conv-valid');
      await expect(service.validateLock(lock.lockToken))
        .rejects
        .toThrow();
    });
  });

  /**
   * Test Suite: Performance Benchmarks
   */
  describe('Performance Benchmarks', () => {
    it('should manage 10000 locks with <1s total time', async () => {
      mockRedis.set.mockResolvedValue('OK');

      const startTime = Date.now();
      const promises = [];

      for (let i = 0; i < 10000; i++) {
        promises.push(service.acquireLock(`conv-bench-${i}`));
      }

      await Promise.all(promises);
      const elapsed = Date.now() - startTime;

      console.log(`10000 lock acquisitions: ${elapsed}ms`);
      expect(elapsed).toBeLessThan(2000);
    });
  });
});

