/**
 * Create test Express app with Phase 4 middleware
 */
const createTestApp = (services) => {
  const app = express();
  app.use(express.json());

  // Mock auth middleware
  app.use((req, res, next) => {
    req.user = {
      shopId: 'shop-123',
      userId: 'user-456',
      role: 'owner'
    };
    next();
  });

  // Phase 4 endpoint
  app.post('/api/chat/message', async (req, res, next) => {
    try {
      const { conversationId, message } = req.body;
      const { shopId, userId } = req.user;

      // Step 1: Acquire conversation lock
      const lock = await services.conversationLock.acquireLock(conversationId);

      try {
        // Step 2: Route intent
        const routing = await services.intentRouter.routeIntent(message, shopId);

        let response;
        if (routing.tier <= 2 && routing.confidence > 0.7) {
          response = routing.response;
        } else {
          // Step 3: Generate response (LLM)
          const llmResult = await services.llmFailover.executeWithFailover(
            message,
            `You are a helpful customer service bot for ${shopId}`,
            {}
          );
          response = llmResult.response;

          // Step 4: Validate cost
          const costResult = await services.costCap.validateCost(
            shopId,
            llmResult.tokens,
            llmResult.provider,
            'model-name'
          );

          if (!costResult.withinLimit) {
            return res.status(402).json({
              success: false,
              error: { code: 'COST_EXCEEDED', message: 'Cost cap exceeded' }
            });
          }
        }

        // Step 5: Validate output (guardrails)
        const guardResult = await services.guardrail.validateOutput(
          message,
          response,
          { shopId, userId, conversationId }
        );

        if (!guardResult.allPassed) {
          return res.status(400).json({
            success: false,
            error: {
              code: 'GUARDRAIL_VIOLATION',
              message: 'Response failed security checks',
              violations: guardResult.violations
            }
          });
        }

        // Step 6: Release lock
        await services.conversationLock.releaseLock(lock.lockToken);

        res.json({
          success: true,
          data: {
            conversationId,
            response,
            tier: routing.tier,
            confidence: routing.confidence,
            costIncurred: 0.015
          }
        });
      } catch (pipelineError) {
        await services.conversationLock.releaseLock(lock.lockToken);
        throw pipelineError;
      }
    } catch (error) {
      next(error);
    }
  });

  // Error handler
  app.use((err, req, res, next) => {
    res.status(err.statusCode || 500).json({
      success: false,
      error: {
        code: err.code || 'INTERNAL_ERROR',
        message: err.message
      }
    });
  });

  return app;
};

