 * 
 * @file tests/phase4/response-format.test.js
 */

const request = require('supertest');
const express = require('express');
const { AppError } = require('../../src/utils/app-error');

/**
 * Standard Response Format:
 * Success: { success: true, data: {...}, metadata: {...} }
 * Error: { success: false, error: { code: 'ERROR_CODE', message: '...' } }
 */

const createTestApp = () => {
  const app = express();
  app.use(express.json());

  // Mock auth
  app.use((req, res, next) => {
    req.user = { shopId: 'shop-123' };
    next();
  });

  // Success endpoint
  app.post('/api/test/success', (req, res) => {
    res.status(200).json({
      success: true,
      data: {
        message: 'Operation successful',
        timestamp: new Date().toISOString()
      },
      metadata: {
        requestId: 'req-123',
        version: '1.0.0'
      }
    });
  });

  // Error endpoint
  app.post('/api/test/error', (req, res) => {
    res.status(400).json({
      success: false,
      error: {
        code: 'INVALID_REQUEST',
        message: 'Request validation failed'
      }
    });
  });

  // Not found endpoint
  app.get('/api/test/not-found', (req, res) => {
    res.status(404).json({
      success: false,
      error: {
        code: 'NOT_FOUND',
        message: 'Resource not found'
      }
    });
  });

  // Unauthorized endpoint
  app.get('/api/test/unauthorized', (req, res) => {
    res.status(401).json({
      success: false,
      error: {
        code: 'UNAUTHORIZED',
        message: 'Authentication required'
      }
    });
  });

  // Forbidden endpoint
  app.get('/api/test/forbidden', (req, res) => {
    res.status(403).json({
      success: false,
      error: {
        code: 'FORBIDDEN',
        message: 'Access denied'
      }
    });
  });

  // Server error endpoint
  app.get('/api/test/server-error', (req, res) => {
    res.status(500).json({
      success: false,
      error: {
        code: 'INTERNAL_ERROR',
        message: 'Internal server error'
      }
    });
  });

  // Array response endpoint
  app.get('/api/test/list', (req, res) => {
    res.status(200).json({
      success: true,
      data: [
        { id: '1', name: 'Item 1' },
        { id: '2', name: 'Item 2' }
      ],
      count: 2,
      pagination: {
        page: 1,
        pageSize: 2,
        total: 2
      }
    });
  });

  // Paginated endpoint
  app.get('/api/test/paginated', (req, res) => {
    res.status(200).json({
      success: true,
      data: Array(10).fill({ id: 'item' }),
      pagination: {
        page: parseInt(req.query.page) || 1,
        pageSize: 10,
        total: 50,
        totalPages: 5
      }
    });
  });

  // Error handler
  app.use((err, req, res, next) => {
    res.status(err.statusCode || 500).json({
      success: false,
      error: {
        code: err.code || 'INTERNAL_ERROR',
        message: err.message
      }
    });
  });

  return app;
};

